	const struct iphdr *iph;
	const struct ipv6hdr *ipv6h;
	struct iphdr _iph;
	struct ipv6hdr _ipv6h;

	if (skb->protocol == htons(ETH_P_IP)) {
		iph = skb_header_pointer(skb, 0, sizeof(_iph), &_iph);
