			is_multicast = true;
		else
			is_multicast = ipv4_is_multicast(iph->daddr);
	} else if (skb->protocol == htons(ETH_P_IPV6)) {
		ipv6h = skb_header_pointer(skb, 0, sizeof(_ipv6h), &_ipv6h);
		if (!ipv6h)
			is_multicast = true;
		else
			is_multicast = ipv6_addr_is_multicast(&ipv6h->daddr);
	} else {
		is_multicast = true;
	}
	break;
}
default:
	WARN_ON(1);
	break;

